def transform(grid):
    h, w = len(grid), len(grid[0])
    # Determine the colored diagonals' offsets and tile their repeating motif.
    marks = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                marks[c-r] = v
    offsets = sorted(marks)
    # Fill with colors by the smallest repeat cycle that preserves distinct
    # colors on the observed diagonal offsets; unmarked lanes repeat blank.
    period = max(offsets) - min(offsets) + 1
    motif = {d % period: v for d, v in marks.items()}
    return [[motif.get((c-r) % period, 0) for c in range(w)] for r in range(h)]

